import {KEY,read,save,validate} from './core.mjs';
function newToken(){return Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join('-');}
const $=id=>document.getElementById(id);let mode='fixed', token=newToken(), memory=[];
function notice(message,error=false){$('notice').textContent=message;$('notice').className=error?'error':'';}
function render(){let rows;try{rows=mode==='fixed'?read(localStorage):memory;}catch(e){notice(e.message,true);rows=[];} $('count').textContent=String(rows.length);$('requests').replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='No saved requests in this version.';$('requests').append(p);}for(const r of [...rows].reverse()){const el=document.createElement('article');el.className='row';for(const [tag,text]of [['strong',r.company],['small',r.email],['p',r.details],['small',`Saved ${new Date(r.created).toLocaleString()}`]]){const node=document.createElement(tag);node.textContent=text;el.append(node);}$('requests').append(el);}}
function setMode(next){mode=next;memory=[];token=newToken();$('before').setAttribute('aria-pressed',String(next==='before'));$('fixed').setAttribute('aria-pressed',String(next==='fixed'));$('mode-note').textContent=next==='fixed'?'Fixed version: requests are saved in this browser and appear in the dashboard after a reload. No server or message is involved.':'Before fixture: the success message is deliberately misleading; the request exists only in memory and is lost on reload. This defect is intentionally reproduced.';try{sessionStorage.setItem('mvp-rescue-mode',mode);}catch{}notice('Version selected. Ready for a fictional request.');render();}
$('before').onclick=()=>setMode('before');$('fixed').onclick=()=>setMode('fixed');
$('request-form').onsubmit=e=>{e.preventDefault();$('submit').disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(mode==='before'){const clean=validate(data);memory.push({...clean,id:token,created:new Date().toISOString()});notice('Prototype says: Saved successfully. (Intentionally misleading — reload to reveal the defect.)');}else{const result=save(localStorage,data,token);notice(result.duplicate?'Already saved. No duplicate request was created.':'Saved in this browser. Reload to verify persistence.');}render();}catch(err){notice(err.message,true);}finally{$('submit').disabled=false;}};
$('new').onclick=()=>{token=newToken();notice('New submission started. Edit the form and save.');};
$('reload').onclick=()=>location.reload();
$('export').onclick=()=>{try{const rows=mode==='fixed'?read(localStorage):memory;const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,requests:rows},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mvp-rescue-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Export created from the current demo version.');}catch(e){notice(e.message,true);}};
$('reset').onclick=()=>$('confirm').showModal();$('cancel').onclick=()=>$('confirm').close();$('erase').onclick=()=>{try{if(mode==='fixed')localStorage.removeItem(KEY);memory=[];token=newToken();$('confirm').close();notice('Demo data deleted.');render();}catch(e){notice(e.message,true);}};
try{const saved=sessionStorage.getItem('mvp-rescue-mode');if(saved==='before')mode='before';}catch{}setMode(mode);
